const ORDER = Object.keys(GROUPS);
const humanize = (segment) => segment.split("-").map((word) => word[0].toUpperCase() + word.slice(1)).join(" ");

function group(key, items) {
  const { label, translations } = GROUPS[key] ?? { label: humanize(key.split("/").at(-1)), translations: {} };
  return { label, translations, collapsed: true, items };
}

export function sidebarFromTopics(slugs) {
  const sections = new Map();
  for (const slug of slugs.filter(Boolean).sort()) {
    const parts = slug.split("/");
    const key = parts.length === 1 ? PROJECT : parts.length === 2 ? parts[0] : parts.slice(0, 2).join("/");
    sections.set(key, [...(sections.get(key) ?? []), { autogenerate: { directory: slug } }]);
  }
  const keys = [...sections.keys()];
  const rank = (key) => (key === PROJECT ? Infinity : ORDER.indexOf(key.split("/")[0]) === -1 ? ORDER.length : ORDER.indexOf(key.split("/")[0]));
  const tops = [...new Set(keys.map((key) => key.split("/")[0]))].sort((a, b) => rank(a) - rank(b));
  return tops.map((top) => {
    if (top === PROJECT) return group(PROJECT, sections.get(PROJECT));
    const nested = keys.filter((key) => key !== top && key.split("/")[0] === top).sort()
      .map((key) => group(key, sections.get(key)));
    return group(top, [...(sections.get(top) ?? []), ...nested]);
  });
}
